import java.io.*;import java.security.*;import java.util.*;
public final class TestDecoder {
 public static void main(String[] args)throws Exception {
  File[] files=new File(args[0]).listFiles();int count=0;long bytes=0,nanos=0;
  for(File f:files)if(f.getName().endsWith(".lzma")){
   byte[] raw=java.nio.file.Files.readAllBytes(new File(f.toString().replace(".lzma",".raw")).toPath());DataInputStream in=new DataInputStream(new FileInputStream(f));byte[] props=new byte[5];in.readFully(props);long size=0;for(int i=0;i<8;i++)size|=(long)in.readUnsignedByte()<<(i*8);
   lzma.sdk.lzma.Decoder dec=new lzma.sdk.lzma.Decoder();if(!dec.setDecoderProperties(props))throw new Exception("props");ByteArrayOutputStream out=new ByteArrayOutputStream();long t=System.nanoTime();boolean ok=dec.code(in,out,size);nanos+=System.nanoTime()-t;in.close();if(!ok||!Arrays.equals(raw,out.toByteArray()))throw new Exception("mismatch "+f);count++;bytes+=raw.length;
  }
  System.out.println("Exact LZMA1 roundtrip fixtures="+count+" bytes="+bytes+" desktop_decode_ms="+nanos/1000000);
 }
}

